private RecipeConformanceDetails computeConformance(String batchKey, BatchRecipeRow binding, List<IngredientRow> ingredients) {
    Map<String, BigDecimal> actual = new HashMap<>();
    for (WeighingRow w : recipeRepo.findEffectiveWeighings(batchKey)) {
        actual.merge(w.ingredient(), w.mass(), BigDecimal::add);
    }
    BigDecimal totalActual = actual.values().stream().reduce(BigDecimal.ZERO, BigDecimal::add);
    BigDecimal target = binding.targetMass();
    boolean totalMatches = totalActual.compareTo(target) == 0;
    List<IngredientTotal> totals = new ArrayList<>();
    boolean allWeighed = true; boolean allWithin = true;
    for (IngredientRow ing : ingredients) {
        BigDecimal expectedMass = ing.percentage().multiply(target).divide(HUNDRED); // exact? percentage scale<=4, target scale<=6 → product scale<=10; /100 exact → scale<=8? divide by 100: scale reduces by 2 → exact always (100 = 10^2). Yes exact.
        BigDecimal actualMass = actual.get(ing.ingredient());
        boolean weighed = actualMass != null;
        if (!weighed) allWeighed = false;
        boolean within = weighed && totalActual.signum() > 0 && withinTolerance(actualMass, ing.percentage(), totalActual);
        if (!within) allWithin = false;
        BigDecimal massDiff = weighed ? actualMass.subtract(expectedMass) : null;
        BigDecimal deviation = weighed && totalActual.signum() > 0
            ? actualMass.multiply(HUNDRED).divide(totalActual, 10, RoundingMode.HALF_UP).subtract(ing.percentage()).setScale(6, RoundingMode.HALF_UP).stripTrailingZeros()
            : null;
        totals.add(new IngredientTotal(ing.ingredient(), ing.percentage(), expectedMass, actualMass, massDiff, deviation, weighed, within));
    }
    boolean conforms = allWeighed && totalMatches && allWithin;
    return new RecipeConformanceDetails(batchKey, target, totalActual, totalActual.subtract(target), totalMatches, conforms, List.copyOf(totals));
}
