```java
private boolean withinTolerance(BigDecimal actualMass, BigDecimal percentage, BigDecimal totalActual) {
    // |actual/total*100 - percentage| <= 0.1  <=>  |1000*actual - 10*percentage*total| <= total
    BigDecimal lhs = actualMass.multiply(BigDecimal.valueOf(1000))
            .subtract(percentage.multiply(BigDecimal.TEN).multiply(totalActual)).abs();
    return lhs.compareTo(totalActual) <= 0;
}
