public SplitInheritance planSplitInheritance(String parentKey, List<SplitRequest.ChildSpec> children) {
    var bindingOpt = recipeRepo.findBatchRecipe(parentKey);
    boolean anyTarget = children.stream().anyMatch(c -> c.targetMass() != null);
    if (bindingOpt.isEmpty()) {
        if (anyTarget) throw ApiException.badRequest("父批未绑定配方，子批不得指定 targetMass");
        return null;
    }
    BatchRecipeRow binding = bindingOpt.get();
    for (child : children) {
        if (child.targetMass() == null) throw badRequest("父批已绑定配方，子批必须指定 targetMass");
        validateMass(child.targetMass(), "targetMass"); // 400
    }
    BigDecimal sum = children.stream().map(ChildSpec::targetMass).reduce(BigDecimal.ZERO, BigDecimal::add);
    if (sum.compareTo(binding.targetMass()) != 0) {
        throw ApiException.unprocessable("子批目标总质量之和 " + sum + " 不等于父批目标总质量 " + binding.targetMass() + "，无法守恒");
    }
    List<IngredientRow> ingredients = recipeRepo.findIngredients(binding.recipeKey(), binding.recipeVersion());
    Map<String, BigDecimal> actual = effectiveTotals(parentKey);
    List<ChildPlan> plans = new ArrayList<>();
    for (child : children) {
        List<IngredientMass> masses = new ArrayList<>();
        for (ing : ingredients) {
            BigDecimal parentMass = actual.getOrDefault(ing.ingredient(), BigDecimal.ZERO);
            BigDecimal product = parentMass.multiply(child.targetMass());
            BigDecimal quotient;
            try {
                quotient = product.divide(binding.targetMass());
            } catch (ArithmeticException e) {
                throw unprocessable("成分 " + ing.ingredient() + " 的质量按比例拆分后无法在 6 位小数内守恒");
            }
            if (quotient.stripTrailingZeros().scale() > MASS_SCALE) {
                throw unprocessable(... 422 ...);
            }
            masses.add(new IngredientMass(ing.ingredient(), quotient.setScale(MASS_SCALE)));
        }
        plans.add(new ChildPlan(child.batchKey(), child.targetMass(), masses));
    }
    return new SplitInheritance(binding, plans);
}
